insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_khandadhar_sng','Khandadhar Waterfall (Sundargarh)','Odisha','Sundargarh','Waterfall','Khandadhar in Sundargarh is a breathtaking 244-meter (801 ft) perennial cascade resembling a sharp sword edge (''Khanda Dhara''). Encircling dense virgin forests of the Chelligarh mountain range, it is one of eastern India''s most dramatic natural spectacles.','21.9056','85.0083','needs_review','October – March','1',array['waterfall','highest waterfall','trekking','forest','sal woods','adventure']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
