insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_akhandalamani','Baba Akhandalamani Temple (Aradi)','Odisha','Bhadrak','Temple','Situated on the banks of river Baitarani, the Baba Akhandalamani Temple is revered throughout Eastern India. Devotees from Odisha, Bengal, and Jharkhand visit to seek blessings for relief from ailments. The present temple structure was patronized by King Niladri Dingh in the 17th century.','20.8841','86.6894','needs_review','October – March','1',array['shiva','temple','river baitarani','spiritual','healing','pilgrimage']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
