insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_debrigarh','Debrigarh Wildlife Sanctuary & Eco-Resort','Odisha','Bargarh','Wildlife','Debrigarh Wildlife Sanctuary spans 353 sq km along the Barapahad hills bordering the vast Hirakud Reservoir. Renowned for its high wildlife density, visitors routinely spot Indian bison (gaur), leopards, sambar, and the elusive Chousingha (four-horned antelope). Historically, legendary freedom fighter Veer Surendra Sai used Debrigarh''s rocky terrain for his guerrilla war against the British.','21.65','83.75','needs_review','November – April','2',array['wildlife','safari','chousingha','hirakud lake','leopard','eco cottages','freedom fighter']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
