insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_majhigouri','Maa Majhigouri Temple (Rayagada)','Odisha','Rayagada','Temple','Maa Majhigouri Temple in Rayagada is a unique and deeply revered Shakti shrine. Unlike traditional temples, the deity is enshrined in an open-air sanctum beneath the sky, adhering to centuries-old tribal and folk customs. Pilgrims from across Odisha, Andhra Pradesh, and Chhattisgarh visit to perform puja.','19.1683','83.4167','needs_review','September – March','1',array['shakti','temple','tribal folklore','rayagada','spiritual','living traditions']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
