insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_chatikona','Chatikona Waterfalls & Niyamgiri Foothills','Odisha','Rayagada','Waterfall','Chatikona sits in a verdant valley flanked by the legendary Niyamgiri hill range. The perennial stream cascades down granite steps amid lush woods near the Shiva temple. Every Wednesday, the famous Chatikona weekly market draws the indigenous Dongria Kondh community dressed in traditional hand-woven shawls with brass jewelry.','19.45','83.45','needs_review','October – March','1',array['waterfall','niyamgiri','dongria kondh','hills','tribal market','nature']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
