insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_hanging_bridge','Nagavali Hanging Bridge & Chekaguda','Odisha','Rayagada','Nature','Constructed over the rocky gorge of river Nagavali, the 151-meter Chekaguda suspension bridge is an engineering and visual highlight of Rayagada. Swaying gently over turquoise river rapids framed by eastern ghat hilltops, it offers breathtaking photography.','19.1833','83.4333','needs_review','September – March','1',array['bridge','suspension bridge','river','nagavali','scenic','architecture']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_phurlijharan','Phurlijharan Waterfall','Odisha','Kalahandi','Waterfall','Phurlijharan is a beloved natural jewel of Kalahandi, situated 16 km from the district headquarters of Bhawanipatna. Dropping from a height of 16 meters (52 feet) over a terraced cliff into a clear pool, the splashing spray creates rainbow arcs in morning sunlight.','19.8667','83.1167','needs_review','October – March','1',array['waterfall','perennial','rainbow','forest','picnic','bhawanipatna']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
