insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_asurgarh','Asurgarh Ancient Fort & Archaeological Site','Odisha','Kalahandi','Heritage','Asurgarh is one of the oldest planned fortified cities in Eastern India, with radiocarbon dating confirming human settlement from the 3rd century BC through the 5th century AD. Excavations by the Archaeological Survey of India uncovered red-slipped pottery, silver punch-marked coins, and ornate beads demonstrating vibrant ancient trans-continental trade.','19.9833','83.35','needs_review','October – March','1',array['archaeology','3rd century bc','fort','excavation','history','moat']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_balimela','Balimela Reservoir & Gurupriya Bridge','Odisha','Malkangiri','Lake','Balimela on river Sileru forms an astonishingly beautiful inland sea of crystal turquoise waters. The historic 910-meter Gurupriya Bridge has connected the isolated ''Swabhiman Anchal'' (Cut-off Area) with mainland Odisha, opening up awe-inspiring views of emerald hill islands.','18.2333','82.1167','needs_review','October – March','2',array['reservoir','swabhiman anchal','gurupriya bridge','hills','boating','spectacular']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_satiguda_dam','Satiguda Dam & Eco-Park','Odisha','Malkangiri','Lake','Located just 8 km from Malkangiri town, Satiguda Dam is a serene escape where visitors enjoy paddle boating, children''s park rides, and sunset panoramas against the backdrop of dense Sal and Teak forests.','18.3583','81.8917','needs_review','October – March','1',array['dam','eco-park','boating','sunset','peaceful','nature']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_bonda_hills','Bonda Hills & Mudulipada','Odisha','Malkangiri','Heritage','The Bonda Hills in Malkangiri are the ancestral homeland of the Bonda (Remo) tribe, recognized as one of India''s Particularly Vulnerable Tribal Groups (PVTGs). Living in high mountain isolation for millennia, they have preserved ancient linguistic, textile, and societal traditions.','18.3833','82.25','needs_review','November – February','1',array['bonda tribe','pvtg','ancient culture','hills','heritage','rare']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_chandan_dhara','Chandan Dhara Waterfall','Odisha','Nabarangpur','Waterfall','Chandan Dhara is situated along the river Turi in the Jharigam block of Nabarangpur district. The sparkling cascade plunges over rock ledges in the heart of dense sal forests. The nearby Lord Shiva temple makes it both a popular spiritual site and an idyllic winter picnic spot.','19.65','82.2667','needs_review','October – February','1',array['waterfall','river turi','shiva','forest','chandan dhara','nature']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_paparahandi','Shahid Smruti Stambha (Paparahandi)','Odisha','Nabarangpur','Heritage','Paparahandi is the sacred ''Jallianwala Bagh of Odisha''. On August 24, 1942, during the Quit India movement, British police opened fire on thousands of peaceful tribal freedom fighters crossing the wooden bridge over river Turi. A majestic martyrs'' memorial (Shahid Stambha) commemorates the sacrifice.','19.3333','82.5167','needs_review','October – March','1',array['freedom struggle','quit india','martyrs','river turi','memorial','history']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
